/* Puff · 消息列表粉白立体终极美化版 */

/* ========== A. 变量调整 ========== */

.chat-app {

  --dress-list-sheet-radius: 0px !important;

  --dress-list-row-pad-y: 12px;

  --dress-list-row-pad-x: 14px;

  --dress-list-preview-size: 11px;

  --dress-list-name-size: 0.9375rem;

  --dress-list-unread-bg: #FFB6C1; 

  --dress-list-unread-fg: #FFF;

  --cherry: #FFB6C1;        

  --cherry-light: #FFD1DC;  

  --shadow-pink: rgba(255, 182, 193, 0.7); 

  --highlight: #FFFFFF;

}

html[data-theme="dark"] .chat-app {

  --dress-list-unread-bg: #f0f0f0;

  --dress-list-unread-fg: #1a1a1a;

}

/* ========== B. 页面壳 / 顶栏 ========== */

.chat-app {

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-b87512ae-d5a0-4089-b4fb-25768e835bea.jpg');

  background-size: cover;

  background-position: center;

  background-color: #FFF5F8; 

}

/* 顶栏：直角立体，加厚高光 */

.chat-head, .chat-head-inbox {

  border-radius: 0 !important;

  border: 4px solid #FFFFFF;

  background: linear-gradient(145deg, #FFFFFF, #FFF0F3);

  box-shadow: 

    0 0 0 4px #FFD1DC,

    6px 6px 14px var(--shadow-pink),

    -4px -4px 10px #FFFFFF,

    inset 3px 3px 6px #FFFFFF,

    inset -3px -3px 6px #FFD1DC;

  margin-bottom: 12px;

}

/* 顶栏标题和筛选按钮（强化立体感，增加按压回弹） */

.chat-inbox-title, .chat-inbox-filter {

  color: #FF8AA1; 

  font-weight: 800;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

}

.chat-inbox-filter button {

  border-radius: 0 !important;

  background: #FFF0F3;

  color: #FF8AA1;

  border: 1px solid #fff;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

  transition: all 0.2s;

}

.chat-inbox-filter button:active {

  transform: scale(0.92);

}

.chat-inbox-filter button.on {

  background: #FFB6C1;

  color: #FFFFFF;

  box-shadow: inset 3px 3px 6px rgba(255, 182, 193, 0.8), inset -3px -3px 6px #FFD1DC;

  text-shadow: none;

}

/* ========== C. 表体 ========== */

.chat-list-sheet {

  border-radius: 0 !important;

  background: transparent;

  box-shadow: none;

  overflow: visible;

}

.chat-scroll {

  padding: 4px; 

}

/* ========== D. 会话行（硬直角 + 锐利字体 + 出场动效） ========== */

.chat-row-wrap {

  margin-bottom: 10px;

  position: relative;

  /* 增加列表的错落弹跳出场动画 */

  animation: bounce-in 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275) backwards;

}

.chat-row-wrap:nth-child(1) { animation-delay: 0.0s; }

.chat-row-wrap:nth-child(2) { animation-delay: 0.05s; }

.chat-row-wrap:nth-child(3) { animation-delay: 0.1s; }

.chat-row-wrap:nth-child(4) { animation-delay: 0.15s; }

.chat-row-wrap:nth-child(5) { animation-delay: 0.2s; }

@keyframes bounce-in {

  0% { opacity: 0; transform: translateY(20px) scale(0.95); }

  100% { opacity: 1; transform: translateY(0) scale(1); }

}

.chat-row {

  border-radius: 0 !important;

  background: linear-gradient(145deg, #FFFFFF, #FFEEF2);

  border: 4px solid #FFFFFF; 

  box-shadow: 

    0 0 0 4px #FFD1DC,

    6px 6px 14px var(--shadow-pink),

    -4px -4px 10px #FFFFFF,

    inset 3px 3px 6px #FFFFFF,

    inset -3px -3px 6px #FFD1DC;

  transition: transform 0.15s ease;

}

/* 【新增】置顶行：特殊粉白渐变背景+深粉外框，突出显示 */

.chat-row-wrap.is-pinned .chat-row {

  background: linear-gradient(145deg, #FFF0F3, #FFDCE5);

  box-shadow: 

    0 0 0 4px #FF9EB5,

    8px 8px 18px var(--shadow-pink),

    -4px -4px 10px #FFFFFF,

    inset 3px 3px 6px #FFFFFF,

    inset -3px -3px 6px #FFC6D3;

}

/* 头像改为硬直角方形（白边+粉色线框） */

.chat-ava-list {

  border-radius: 0 !important;

  border: 2px solid #FFFFFF;

  box-shadow: 0 0 0 2px #FFB6C1;

}

/* 行内文字颜色（浅粉粉白 + 加粗白描边） */

.chat-row-top strong {

  color: #FF8AA1;

  font-size: var(--dress-list-name-size);

  font-weight: 700;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

}

.chat-row-preview {

  color: #FFB6C1;

  font-size: var(--dress-list-preview-size);

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

}

/* 【新增】时间戳：加入硬白底色切片，防吃字 */

.chat-row-meta {

  color: #FF8AA1;

  background: rgba(255,255,255,0.8);

  padding: 2px 4px;

  border: 1px solid #FFD1DC;

  border-radius: 0 !important;

  font-weight: 600;

}

/* 未读数改成了硬直角小方块 */

.chat-row-unread {

  background: var(--dress-list-unread-bg);

  color: var(--dress-list-unread-fg);

  border-radius: 0 !important;

  box-shadow: 2px 2px 4px rgba(255, 182, 193, 0.7), -2px -2px 4px #FFFFFF;

}

/* ========== E. 侧滑操作（保持硬直立体） ========== */

.chat-row-action {

  border-radius: 0 !important;

  background: #FFEEF2;

  box-shadow: 4px 4px 8px rgba(255, 182, 193, 0.7), -4px -4px 8px #FFFFFF;

  color: #FF8AA1;

  border: 2px solid #fff;

}

.chat-row-action.is-delete {

  background: #FFB6C1;

  color: #FFFFFF;

}

.chat-row-action.is-pin {

  background: #FFD1DC;

  color: #FFFFFF;

}

/* ========== F. 底栏 Tab（蒙层防乱 + 扫光动效） ========== */

.chat-zero {

  color: #FFB6C1;

  text-shadow: -2px -2px 0 #fff, 2px -2px 0 #fff, -2px 2px 0 #fff, 2px 2px 0 #fff;

}

/* 【优化】底部Tab：给底图叠一层粉白渐变蒙层，防底图太花看不清图标 */

.chat-tabdock {

  border-radius: 0 !important;

  border: 4px solid #FFFFFF;

  background-image: 

    linear-gradient(rgba(255, 240, 243, 0.85), rgba(255, 240, 243, 0.85)), /* 蒙层 */

    url('https://cdn.phototourl.com/free/2026-09-09-ccc3279c-221c-4889-9303-debaf56e2ae3.jpg');

  background-size: cover;

  background-position: center;

  box-shadow: 0 0 0 4px #FFD1DC, 0 -6px 14px var(--shadow-pink);

  overflow: hidden;

}

/* 底栏扫光动效（静态时光影浮动，更灵动） */

.chat-tabdock::before {

  content: '';

  position: absolute;

  top: -50%; left: -60%;

  width: 40%; height: 200%;

  background: linear-gradient(120deg, transparent, rgba(255,255,255,0.6), transparent);

  transform: rotate(25deg);

  animation: slide-shine 4s infinite;

  pointer-events: none;

}

@keyframes slide-shine {

  0% { left: -60%; }

  20% { left: 150%; }

  100% { left: 150%; }

}

.chat-tabdock-pill {

  border-radius: 0 !important;

  background: rgba(255, 255, 255, 0.9); /* 改为纯粉白背景，图标更清晰 */

  color: #FF8AA1;

  border: 2px solid #FFFFFF;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

  box-shadow: inset 2px 2px 4px rgba(255,255,255,0.8), inset -2px -2px 4px rgba(255,182,193,0.6);

  position: relative;

}

.chat-tabdock-pill:active {

  transform: translateY(2px);

  box-shadow: inset 4px 4px 8px rgba(255, 182, 193, 0.8), inset -4px -4px 8px #FFFFFF;

}

/* ========== G. 精致微光点击动画（保持不变） ========== */

.chat-row-wrap::after, .chat-tabdock-pill::after {

  content: '';

  position: absolute;

  top: 50%; left: 50%;

  width: 30%; 

  height: 30%;

  transform: translate(-50%, -50%) scale(0);

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-f28a50e6-2b80-415a-83e2-d1db7c0bdcce.png');

  background-size: cover;

  background-position: center;

  opacity: 0;

  pointer-events: none; 

  z-index: 999;

}

.chat-row-wrap:active::after, .chat-tabdock-pill:active::after {

  animation: tap-pop-subtle 0.35s ease-out forwards;

}

@keyframes tap-pop-subtle {

  0% { opacity: 0.7; transform: translate(-50%, -50%) scale(0.2); }

  50% { opacity: 0.2; transform: translate(-50%, -50%) scale(0.75); }

  100% { opacity: 0; transform: translate(-50%, -50%) scale(1.05); }

}

.chat-row-wrap:active .chat-row {

  transform: translateY(2px);

  box-shadow: 

    0 0 0 4px #FFD1DC,

    inset 4px 4px 8px var(--shadow-pink),

    inset -4px -4px 8px #FFFFFF;

}
